text:
{
  "claims": [
    {
      "claim_text": "PostgreSQL accepts all four standard transaction isolation levels.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly says PostgreSQL allows requesting any of the four standard levels.",
      "citations": [
        {
          "index": 0,
          "quote": "you can request any of the four standard transaction isolation levels"
        }
      ]
    },
    {
      "claim_text": "PostgreSQL only implements three distinct isolation behaviors internally.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that internally only three distinct isolation levels are implemented.",
      "citations": [
        {
          "index": 0,
          "quote": "internally only three distinct isolation levels are implemented"
        }
      ]
    },
    {
      "claim_text": "Read Uncommitted is treated identically to Read Committed.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says PostgreSQL's Read Uncommitted mode behaves like Read Committed.",
      "citations": [
        {
          "index": 0,
          "quote": "PostgreSQL's Read Uncommitted mode behaves like Read Committed"
        }
      ]
    },
    {
      "claim_text": "Read Committed is the default isolation level.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly names Read Committed as the default.",
      "citations": [
        {
          "index": 2,
          "quote": "Read Committed is the default isolation level in PostgreSQL"
        }
      ]
    },
    {
      "claim_text": "Under Read Committed, a SELECT sees a snapshot of data committed as of the instant the query begins.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says a SELECT sees a snapshot as of the instant the query begins to run.",
      "citations": [
        {
          "index": 2,
          "quote": "In effect, a SELECT query sees a snapshot of the database as of the instant the query begins to run."
        }
      ]
    },
    {
      "claim_text": "Under Read Committed, two SELECTs in one transaction can observe different data if other transactions commit in between.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly describes two successive SELECTs seeing different data in that situation.",
      "citations": [
        {
          "index": 2,
          "quote": "two successive SELECT commands can see different data, even though they are within a single transaction, if other transactions commit changes after the first SELECT starts and before the second SELECT starts"
        }
      ]
    },
    {
      "claim_text": "Repeatable Read takes its snapshot at the start of the first non-transaction-control statement in the transaction.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states this exact snapshot timing for repeatable read.",
      "citations": [
        {
          "index": 4,
          "quote": "a query in a repeatable read transaction sees a snapshot as of the start of the first non-transaction-control statement in the transaction"
        }
      ]
    },
    {
      "claim_text": "Under Repeatable Read, all queries in a transaction see the same stable view.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says successive SELECTs see the same data and that Repeatable Read gives a stable view.",
      "citations": [
        {
          "index": 4,
          "quote": "successive SELECT commands within a single transaction see the same data"
        },
        {
          "index": 5,
          "quote": "The Repeatable Read mode provides a rigorous guarantee that each transaction sees a completely stable view of the database."
        }
      ]
    },
    {
      "claim_text": "Repeatable Read prevents phantom reads.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage directly says PostgreSQL's Repeatable Read implementation does not allow phantom reads.",
      "citations": [
        {
          "index": 1,
          "quote": "PostgreSQL's Repeatable Read implementation does not allow phantom reads"
        }
      ]
    },
    {
      "claim_text": "Repeatable Read exceeds the SQL standard's minimum requirements for that isolation level.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage calls it a stronger guarantee than the SQL standard requires.",
      "citations": [
        {
          "index": 3,
          "quote": "This is a stronger guarantee than is required by the SQL standard for this isolation level"
        }
      ]
    },
    {
      "claim_text": "Repeatable Read does not prevent serialization anomalies.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says Repeatable Read prevents all listed phenomena except serialization anomalies.",
      "citations": [
        {
          "index": 3,
          "quote": "except for serialization anomalies"
        }
      ]
    },
    {
      "claim_text": "Under Repeatable Read, a transaction may see a state that never existed in any serial execution.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says the view is not necessarily consistent with any serial execution.",
      "citations": [
        {
          "index": 5,
          "quote": "this view will not necessarily always be consistent with some serial (one at a time) execution of concurrent transactions of the same level"
        }
      ]
    },
    {
      "claim_text": "For example, Repeatable Read may read an updated control record but a stale detail record.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage gives this exact example.",
      "citations": [
        {
          "index": 5,
          "quote": "even a read-only transaction at this level may see a control record updated to show that a batch has been completed but not see one of the detail records which is logically part of the batch"
        }
      ]
    },
    {
      "claim_text": "Enforcing business rules at Repeatable Read typically requires explicit locking.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage warns business-rule enforcement at this level is unlikely to work without explicit locks.",
      "citations": [
        {
          "index": 5,
          "quote": "Attempts to enforce business rules by transactions running at this isolation level are not likely to work correctly without careful use of explicit locks to block conflicting transactions."
        }
      ]
    },
    {
      "claim_text": "Explicit locking options at Read Committed or Repeatable Read include SELECT FOR UPDATE or table-level locks.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage mentions taking a lock on an entire table or using SELECT FOR UPDATE/SHARE for Read Committed or Repeatable Read.",
      "citations": [
        {
          "index": 8,
          "quote": "a Read Committed or Repeatable Read transaction which wants to ensure data consistency may need to take out a lock on an entire table, which could block other users attempting to use that table, or it may use SELECT FOR UPDATE or SELECT FOR SHARE"
        }
      ]
    },
    {
      "claim_text": "Serializable was implemented since version 9.1.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says prior to 9.1 Serializable provided the older behavior and that legacy behavior is now requested via Repeatable Read, implying the current Serializable behavior dates from 9.1.",
      "citations": [
        {
          "index": 6,
          "quote": "Prior to PostgreSQL version 9.1, a request for the Serializable transaction isolation level provided exactly the same behavior described here. To retain the legacy Serializable behavior, Repeatable Read should now be requested."
        }
      ]
    },
    {
      "claim_text": "Serializable works exactly like Repeatable Read except that it adds monitoring.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says Serializable works exactly the same as Repeatable Read except for additional monitoring.",
      "citations": [
        {
          "index": 7,
          "quote": "this isolation level works exactly the same as Repeatable Read except that it also monitors for conditions which could make execution of a concurrent set of serializable transactions behave in a manner inconsistent with all possible serial (one at a time) executions of those transactions"
        }
      ]
    },
    {
      "claim_text": "Serializable adds monitoring based on predicate locks.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages connect Serializable monitoring with predicate locking used to guarantee true serializability.",
      "citations": [
        {
          "index": 7,
          "quote": "it also monitors for conditions which could make execution of a concurrent set of serializable transactions behave in a manner inconsistent with all possible serial (one at a time) executions of those transactions"
        },
        {
          "index": 8,
          "quote": "To guarantee true serializability PostgreSQL uses predicate locking"
        }
      ]
    },
    {
      "claim_text": "Predicate locks track read-write dependencies among concurrent transactions.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says predicate locks determine when a write would affect a previous concurrent read and identify dependencies among Serializable transactions.",
      "citations": [
        {
          "index": 8,
          "quote": "it keeps locks which allow it to determine when a write would have had an impact on the result of a previous read from a concurrent transaction, had it run first"
        },
        {
          "index": 8,
          "quote": "They are used to identify and flag dependencies among concurrent Serializable transactions"
        }
      ]
    },
    {
      "claim_text": "Predicate locks never block.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage directly states these locks do not cause blocking.",
      "citations": [
        {
          "index": 8,
          "quote": "these locks do not cause any blocking"
        }
      ]
    },
    {
      "claim_text": "Predicate locks do not contribute to deadlocks.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says they cannot play any part in causing a deadlock.",
      "citations": [
        {
          "index": 8,
          "quote": "can not play any part in causing a deadlock"
        }
      ]
    },
    {
      "claim_text": "If a combination of transactions could produce a result inconsistent with any serial order of execution, one of them is aborted with a serialization failure.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says detection of conditions causing a serialization anomaly triggers a serialization failure and that applications must retry due to serialization failures.",
      "citations": [
        {
          "index": 7,
          "quote": "detection of the conditions which could cause a serialization anomaly will trigger a serialization failure"
        },
        {
          "index": 7,
          "quote": "applications using this level must be prepared to retry transactions due to serialization failures"
        }
      ]
    },
    {
      "claim_text": "You should use Serializable when correctness depends on invariants spanning multiple rows or predicates that are awkward to protect with explicit locks.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages do not give this recommendation or discuss invariants spanning rows as a criterion for choosing Serializable.",
      "citations": []
    },
    {
      "claim_text": "Examples of using Serializable include maintaining aggregate constraints.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages do not mention aggregate constraints or recommend Serializable for them.",
      "citations": []
    },
    {
      "claim_text": "Examples of using Serializable include check-then-act logic.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages mention explicit checking before insert in a Serializable context, but do not state that check-then-act logic is a reason to use Serializable.",
      "citations": []
    },
    {
      "claim_text": "Examples of using Serializable include generating keys from existing data.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages mention generating a new key from the maximum existing key, but not as a recommendation for choosing Serializable.",
      "citations": []
    },
    {
      "claim_text": "Applications using Serializable must be prepared to retry transactions that fail with a serialization error.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly says applications using this level must be prepared to retry due to serialization failures.",
      "citations": [
        {
          "index": 7,
          "quote": "applications using this level must be prepared to retry transactions due to serialization failures"
        }
      ]
    },
    {
      "claim_text": "Serialization failures have SQLSTATE 40001.",
      "verdict": "UNSUPPORTED",
      "reasoning": "No passage states the SQLSTATE code 40001.",
      "citations": []
    },
    {
      "claim_text": "Transactions at Serializable should be kept short.",
      "verdict": "UNSUPPORTED",
      "reasoning": "No passage advises keeping Serializable transactions short.",
      "citations": []
    },
    {
      "claim_text": "At Serializable, monitoring overhead grows with transaction duration and concurrency.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage mentions monitoring overhead, but not that it grows with transaction duration and concurrency.",
      "citations": []
    },
    {
      "claim_text": "At Serializable, the probability of conflicts and retries grows with transaction duration and concurrency.",
      "verdict": "UNSUPPORTED",
      "reasoning": "No passage states this relationship between duration/concurrency and conflict or retry probability.",
      "citations": []
    },
    {
      "claim_text": "Even Serializable can report unique constraint violations if some transactions insert keys without first checking for them.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly describes this possibility for Serializable transactions.",
      "citations": [
        {
          "index": 9,
          "quote": "it is possible to see unique constraint violations caused by conflicts with overlapping Serializable transactions even after explicitly checking that the key isn't present before attempting to insert it"
        }
      ]
    },
    {
      "claim_text": "All Serializable transactions that insert potentially conflicting keys should explicitly check first to avoid unique constraint violations.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says the problem can be avoided by making all such Serializable transactions check first.",
      "citations": [
        {
          "index": 9,
          "quote": "all Serializable transactions that insert potentially conflicting keys explicitly check if they can do so first"
        }
      ]
    },
    {
      "claim_text": "All writers should follow a consistent check-before-insert protocol.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage specifies Serializable transactions that insert potentially conflicting keys, not all writers generally.",
      "citations": []
    },
    {
      "claim_text": "Read Committed combined with SELECT FOR UPDATE can be used to ensure data consistency.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says a Read Committed transaction seeking consistency may use SELECT FOR UPDATE.",
      "citations": [
        {
          "index": 8,
          "quote": "a Read Committed or Repeatable Read transaction which wants to ensure data consistency may need to take out a lock on an entire table, which could block other users attempting to use that table, or it may use SELECT FOR UPDATE or SELECT FOR SHARE"
        }
      ]
    },
    {
      "claim_text": "For simple read-modify-write patterns on single rows, Read Committed combined with SELECT FOR UPDATE is often simpler and faster than Serializable.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages do not compare these approaches for simple single-row read-modify-write patterns.",
      "citations": []
    },
    {
      "claim_text": "Explicit advisory locks are an option.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages do not mention advisory locks.",
      "citations": []
    },
    {
      "claim_text": "For simple read-modify-write patterns on single rows, explicit advisory locks are often simpler and faster than Serializable.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages do not mention advisory locks or this performance comparison.",
      "citations": []
    }
  ]
}
